"""Challenge discovery, adaptive profile dialog, and an explicit WhatsApp handoff."""
from html import escape
from pathlib import Path
import json
import re

CHALLENGE_ROUTE='/whatsapp-challenge/'
CONFIG=json.loads((Path(__file__).parent/'challenge-config.json').read_text())
LOGO=json.loads((Path(__file__).parent/'assets.json').read_text())['logos'][0]['path']
number=CONFIG.get('whatsapp_number','')
if number and not re.fullmatch(r'[1-9]\d{7,14}',number):
    raise ValueError('Challenge WhatsApp number must contain 8–15 international digits, without + or spaces.')

def days():
    return '<div class="challenge-days" aria-hidden="true">'+''.join(f'<i style="--day:{i}"></i>' for i in range(30))+'</div>'

def challenge_promo(compact=False):
    return '''<section class="challenge-promo '''+('is-compact' if compact else '')+'''" aria-labelledby="challenge-invite-title"><div class="wrap"><div class="challenge-promo-mark" aria-hidden="true"><span>30</span><small>TAGE / DEIN START</small>'''+days()+'''</div><div class="challenge-promo-copy"><p class="eyebrow">Die WhatsApp-Challenge</p><h2 id="challenge-invite-title">Ein Anfang.<br>Der zu dir passt.</h2><p>Dein Ziel. Dein Zeitbudget. Dein Rhythmus. Richte deine 30-Tage-Challenge in fünf kurzen Schritten aus – und nimm dein Profil mit in WhatsApp.</p><div class="actions"><a class="btn" href="/whatsapp-challenge/#challenge-start">Meine Challenge finden <span aria-hidden="true">↗</span></a><span class="challenge-micro">5 Fragen · Kein Benutzerkonto</span></div></div></div></section>'''

def build_challenge(page):
    safe_config=json.dumps({k:CONFIG.get(k,'') for k in ['whatsapp_number','price_note','message_keyword','handoff_mode','demo_enabled']},ensure_ascii=False).replace('</','<\\/')
